for expense in trip_expenses:
    lines = expense.split('\n')
    for line in lines:
        if "Owed equally" in line:
            parts = line.split('.')
            person_paid = parts[0].strip()
            amount_paid = parts[1].strip().split('$')[1] if '$' in parts[1].strip() else "0"
            people_owing = parts[2].strip().split(', ')
            trip_name = " ".join(parts[1].strip().split('$')[0].split()[-2:])
            trip_expense_map[trip_name] = trip_expense_map.get(trip_name, []) + [expense]

print(f"Total trip expense maps found: {len(trip_expense_map)}")

